draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // human
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 25);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 15, H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 15, H/2 + 45);
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 25);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 115, H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 85, H/2 + 45);
  ctx.stroke();

  // eye contact
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10 + 10 * Math.sin(t));
  ctx.lineTo(W/2 - 100, H/2 - 10 + 10 * Math.sin(t));
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.lineWidth = 4;

  ctx.restore();
}
